import{_ as e,o as r,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Autopsy- When Erasure Coding Goes Wrong","description":"","frontmatter":{"title":"Ceph Autopsy- When Erasure Coding Goes Wrong","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Erasure Coding","Ceph","Data Consistency","Storage Systems","Tools Development"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Cephalautopsy_-_When_Erasure_Coding_Goes_Wrong.md","filePath":"posts/2025/Cephalautopsy_-_When_Erasure_Coding_Goes_Wrong.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Cephalautopsy_-_When_Erasure_Coding_Goes_Wrong.md"};function n(l,o,i,g,h,u){return r(),t("div",null,[...o[0]||(o[0]=[a('<p>Ceph Autopsy: When Erasure Coding Goes Wrong 这次会议纪要主要讨论了 Erasure Coding (EC) 数据一致性的检测与修复工具的开发进展。以下是会议的关键细节和主要议题：</p><h3 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h3><ul><li><strong>演讲者</strong>：Jamie Pride（IBM UK 团队，负责 Fast EC 改进项目）</li><li><strong>主题</strong>：EC 数据损坏分析与工具开发</li><li><strong>背景</strong>：针对 Erasure Coded 存储池中数据不一致性的检测与修复工具进行讨论。</li></ul><h3 id="关键讨论内容" tabindex="-1">关键讨论内容 <a class="header-anchor" href="#关键讨论内容" aria-label="Permalink to &quot;关键讨论内容&quot;">​</a></h3><h4 id="_1-ec-数据不一致性的原因" tabindex="-1">1. EC 数据不一致性的原因 <a class="header-anchor" href="#_1-ec-数据不一致性的原因" aria-label="Permalink to &quot;1. EC 数据不一致性的原因&quot;">​</a></h4><ul><li><strong>硬件故障</strong>：磁盘故障或固件缺陷可能导致写入错误。</li><li><strong>软件缺陷</strong>：OSD 代码 Bug（概率较低，但需防范）。</li><li><strong>后果</strong>：应用读取错误数据时可能崩溃，重建时依赖的校验数据可能错误。</li></ul><h4 id="_2-复制池-vs-ec-池的差异" tabindex="-1">2. 复制池 vs. EC 池的差异 <a class="header-anchor" href="#_2-复制池-vs-ec-池的差异" aria-label="Permalink to &quot;2. 复制池 vs. EC 池的差异&quot;">​</a></h4><ul><li><strong>复制池</strong>：不一致性易检测。</li><li><strong>EC 池</strong>：需重新计算校验数据并与存储的校验块对比，才能发现不一致性。</li></ul><h4 id="_3-开发中的工具" tabindex="-1">3. 开发中的工具 <a class="header-anchor" href="#_3-开发中的工具" aria-label="Permalink to &quot;3. 开发中的工具&quot;">​</a></h4><ul><li><strong>Offline EC Consistency Checker</strong>：离线扫描 OSD，重新计算校验数据并验证一致性。适用于应用报告数据损坏时定位问题 OSD，或在集群离线维护时预检数据一致性。</li><li><strong>Online EC Consistency Checker</strong>：目标用户为开发者，用于 EC 功能开发时的实时测试。</li></ul><h4 id="_4-工具开发进展与资源" tabindex="-1">4. 工具开发进展与资源 <a class="header-anchor" href="#_4-工具开发进展与资源" aria-label="Permalink to &quot;4. 工具开发进展与资源&quot;">​</a></h4><ul><li><strong>开发者</strong>：Connor Faucet（IBM 团队，未参会）。</li><li><strong>代码仓库</strong>：提供离线和在线工具的 PR 链接。</li><li><strong>计划</strong>：2023 年内完成工具优化并发布用户友好版本。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>完善工具功能，如增加故障 OSD 标识能力，提供详细用户文档和独立部署指南。</li><li>鼓励社区用户试用离线工具并反馈问题，开发者可通过在线工具验证 EC 相关代码变更。</li></ul><h3 id="术语表-保留英文关键词" tabindex="-1">术语表（保留英文关键词） <a class="header-anchor" href="#术语表-保留英文关键词" aria-label="Permalink to &quot;术语表（保留英文关键词）&quot;">​</a></h3><ul><li><strong>EC (Erasure Coding)</strong> | <strong>OSD</strong> | <strong>PG</strong> | <strong>RADOS</strong> | <strong>Teuthology</strong></li><li><strong>Parity</strong> | <strong>Rebuild</strong> | <strong>Consistency Check</strong> | <strong>Object Store Tool</strong></li></ul><p>会议纪要准确反映了原始内容的要点，涵盖了关键细节、讨论的主要议题、决定的事项以及后续的行动计划。没有发现错误、误解或遗漏的重要信息。</p>',17)])])}const c=e(s,[["render",n]]);export{_ as __pageData,c as default};
